import yaml
with open('registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})

# Check s47 for all suites
for suite in ['spatial', 'goal', 'obj', 'long']:
    print(f'--- {suite.upper()} s47 ---')
    for method in ['vla-only', 'crm', 'adapt', 'k2mean', 'reconvla']:
        found = []
        for eid, exp in exps.items():
            if 'eval-supp' in eid and suite in eid.lower() and 's47' in eid and method in eid.lower():
                status = exp.get('status', '?')
                conclusion = exp.get('conclusion', '')
                sr = ''
                if exp.get('metrics'):
                    sr = exp['metrics'].get('overall_success_rate', '')
                found.append(f'{eid}={status}/{conclusion} SR={sr}')
        if found:
            for f in found:
                print(f'  {method}: {f}')
        else:
            print(f'  {method}: MISSING')
" 2>/dev/null
